    """Abstract base tokenizer with generic input type."""

    @abstractmethod
    def tokenize(self, value: T) -> Token:
        """Convert value to token."""
        pass

    def tokenize_batch(self, values: Iterable[T]) -> Iterator[Token]:
        """Lazy tokenization of multiple values."""
        for v in values:
