        self.format_str = format_str

    def tokenize(self, value: datetime | date) -> Token:
        if self.format_str:
            fmt = self.format_str
        elif isinstance(value, datetime):
            fmt = self.ISO_FORMAT
        else:
            fmt = self.DATE_FORMAT

        return Token(value.strftime(fmt), TokenType.TEMPORAL)


