class TokenFunctor[T](private val value: T) {
  def map[B](func: T => B): TokenFunctor[B] = new TokenFunctor(func(value))

  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] = func(value)

  def getOrElse(default: => T): T = if (value != null) value else default

  def get: T = value
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] = {
    TokenMonad(funcWrapped.get.apply(get))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
  def apply[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

