// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def stripPunc(word: String): String = {
    val startStripped = word.dropWhile(punctuation.contains)
    startStripped.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    var w = if (stripPunctuation) stripPunc(word) else word
    if (lowercase) w = w.toLowerCase

    if (w.length < minLength) return None

    maxLength.foreach { max =>
      if (w.length > max) w = w.take(max)
    }

    if (w.isEmpty) None else Some(w)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)
    val tokens = mutable.ListBuffer.empty[Token]

    words.zipWithIndex.foreach { case (word, i) =>
      processToken(word).foreach { processed =>
        tokens += Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").filter(_.nonEmpty).foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

