class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case bytes: Array[Byte] => new String(bytes, encoding)
      case s: String          => s
      case other              => throw new IllegalArgumentException(s"Unsupported type: ${other.getClass}")
    }

    Token(normalizer(strValue), TokenType.STRING)
  }

  def tokenize(value: String): Token = tokenize(value.asInstanceOf[Any])
  def tokenize(value: Array[Byte]): Token = tokenize(value.asInstanceOf[Any])
}

class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case bd: BigDecimal => bd.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
      case d: Double      => f"$d%.${precision}f"
      case f: Float       => f"$f%.${precision}f"
      case i: Int         => i.toString
      case l: Long        => l.toString
      case other          => throw new IllegalArgumentException(s"Unsupported numeric type: ${other.getClass}")
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val ISO_FORMAT = "yyyy-MM-dd'T'HH:mm:ss"
  private val DATE_FORMAT = "yyyy-MM-dd"

  override def tokenize(value: Any): Token = {
    val formatter = value match {
      case _: LocalDateTime => DateTimeFormatter.ofPattern(formatStr.getOrElse(ISO_FORMAT))
      case _: LocalDate     => DateTimeFormatter.ofPattern(formatStr.getOrElse(DATE_FORMAT))
      case other            => throw new IllegalArgumentException(s"Unsupported temporal type: ${other.getClass}")
    }

    val formatted = value match {
      case dt: LocalDateTime => dt.format(formatter)
      case d: LocalDate      => d.format(formatter)
    }

    Token(formatted, TokenType.TEMPORAL)
  }
}

